gnA(){return"\uc0ac\uc6a9 \uc548\ub0b4"},
gnu(){return"TruthLens \uc18c\uac1c"},
gnt(){return'TruthLens\ub294 \ud575\uc2ec AI \ucd94\ub860\uc774 \uc644\uc804\ud788 \uae30\uae30 \ub0b4\uc5d0\uc11c \uc2e4\ud589\ub418\ub294 \ud06c\ub85c\uc2a4 \ud50c\ub7ab\ud3fc \ucf58\ud150\uce20 \uac10\uc9c0 \uc571\uc785\ub2c8\ub2e4\uff08iOS / Android / macOS / Windows\uff09. Transformer \uc2e0\uacbd\ub9dd \ubd84\ub958\uae30, \ud1b5\uacc4\uc801 \ud2b9\uc9d5 \ubd84\uc11d, \ubb38\uccb4 \ud2b9\uc9d5 \ubd84\uc11d, \uc801\ub300\uc801 \ud328\ub7ec\ud504\ub808\uc774\uc988 \uac10\uc9c0\ub77c\ub294 4\uac1c\uc758 \ub3c5\ub9bd\uc801\uc778 \ud558\uc704 \ubaa8\ub378\uc774 \uac00\uc911 \ud22c\ud45c\ub97c \ud1b5\ud574 \ud14d\uc2a4\ud2b8\uac00 AI\ub85c \uc0dd\uc131\ub418\uc5c8\ub294\uc9c0 \ud310\uc815\ud558\uba70, \ubb38\uc7a5 \ub2e8\uc704\ub85c \uc124\uba85 \uac00\ub2a5\ud55c \ubd84\uc11d \uadfc\uac70\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4. \ub2e8\uc21c\ud788 "AI \uac19\uc74c" \ubc31\ubd84\uc728\ub9cc \uc81c\uc2dc\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c "\uc65c" \uadf8\ub7f0\uc9c0 \uc124\uba85\ud569\ub2c8\ub2e4.'},
